# rapids-g (rapids TASK-034): the 8-channel register map, as top/rapids_top_base.f.
# Filelist for rapids_top_base with the 8-channel register map
# Location: projects/components/dma-ip/rapids/rtl/filelists/top_g/rapids_g_top_base.f
#
# The base is one module for both register-map sizes. This file picks the
# map: its regblock (rapids_regs, generated by bin/peakrdl_generate.py)
# and the regsel include dir that tells the base which regblock and glue to use.
# The regblock comes first: the base uses its package.

+incdir+$REPO_ROOT/projects/components/dma-ip/rapids/rtl/top/generated/regsel_8ch

# ---- PeakRDL register file (split SRC/SNK), 8 channels ----
$REPO_ROOT/projects/components/dma-ip/rapids/regs/generated/rtl/rapids_regs_pkg.sv
$REPO_ROOT/projects/components/dma-ip/rapids/regs/generated/rtl/rapids_regs.sv

-f $REPO_ROOT/projects/components/dma-ip/rapids/rtl/filelists/top_g/rapids_g_top_base_common.f

# ---- The base itself, last: it uses the regblock package and the regsel
#      include dir above ----
$REPO_ROOT/projects/components/dma-ip/rapids/rtl/top_g/generated/rapids_g_top_base.sv
